class Solution {
public:
    vector<vector<int>> findWinners(vector<vector<int>>& matches) {
        const int MAXP = 100001;
        int losses[MAXP];
        for (int i = 0; i < MAXP; i++) losses[i] = -1;

        for (auto& m : matches) {
            int w = m[0], l = m[1];
            if (losses[w] == -1) losses[w] = 0;
            if (losses[l] == -1) losses[l] = 0;
            losses[l]++;
        }

        vector<vector<int>> ans(2);
        for (int i = 1; i < MAXP; i++) {
            if (losses[i] == 0) ans[0].push_back(i);
            else if (losses[i] == 1) ans[1].push_back(i);
        }
        return ans;
    }
};
